"""One-off: tokenless answers of the baseline server vs the current one."""

import itertools
import sys

sys.path.insert(0, sys.argv[1])  # holds oldttt/
sys.path.insert(0, sys.argv[2])  # the app
from oldttt import server as old  # noqa: E402

from tictactoe import server as new  # noqa: E402

ADDED = ("game", "stealable", "steal_used", "assisted")
diffs = checked = 0
for cells in itertools.product(["", "X", "O"], repeat=9):
    board = list(cells)
    for mode in ("computer", "friend"):
        for cell in (0, 4, 8, 9, None, True):
            request = {"board": board, "cell": cell, "mode": mode, "level": "hard"}

            def run(module):
                try:
                    return module.handle_move(dict(request))
                except ValueError as error:
                    return ("error", str(error))

            before, after = run(old), run(new)
            if isinstance(after, dict):
                assert set(ADDED) <= set(after)
                after = {k: v for k, v in after.items() if k not in ADDED}
            checked += 1
            if before != after:
                diffs += 1
                print("DIFF", request, before, after)
                if diffs > 5:
                    sys.exit(1)
print("checked", checked, "diffs", diffs)

