# The cheat code's steal (changes/cheat-code/spec.md, rules 1, 2, 4 and 5)


def test_turn_after_a_steal_is_x_when_x_leads_by_one() -> None:
    assert game.turn(board("XX. .O. ..X"), steals=1) == "O"
    assert game.turn(board("XXO .O. ..X"), steals=1) == "X"
    assert game.turn(game.new_board(), steals=1) == "O"


@pytest.mark.parametrize("text", ["... ... ...", "X.. ... ...", "XO. ... ...", "XOX OX. ..."])
def test_without_a_steal_turn_and_validate_are_unchanged(text: str) -> None:
    cells = board(text)
    assert game.turn(cells, steals=0) == game.turn(cells) == ("X" if text.count("O") == text.count("X") else "O")
    assert game.validate(cells, steals=0) == game.validate(cells) == cells


def test_validate_after_a_steal_accepts_x_one_or_two_ahead() -> None:
    assert game.validate(board("XX. .O. ..."), steals=1) == board("XX. .O. ...")
    assert game.validate(board("XX. .O. ..X"), steals=1) == board("XX. .O. ..X")


@pytest.mark.parametrize("text", ["XO. ... ...", "XXX X.. O..", "... ... ..."])
def test_validate_after_a_steal_rejects_other_counts(text: str) -> None:
    with pytest.raises(game.IllegalMoveError, match="alternate"):
        game.validate(board(text), steals=1)


@pytest.mark.parametrize("bad", [None, "X........", [""] * 8, [""] * 10, ["x"] + [""] * 8, [None] * 9])
def test_check_cells_rejects_bad_shapes_and_cells(bad: object) -> None:
    with pytest.raises(game.IllegalMoveError):
        game.check_cells(bad)


def test_check_cells_does_not_check_the_counts() -> None:
    cells = board("XXX X.. ...")
    copy = game.check_cells(cells)
    assert copy == cells
    assert copy is not cells


def test_play_after_a_steal_uses_the_steal_turn_rule() -> None:
    assert game.play(board("XX. .O. ..."), 2, steals=1) == board("XXO .O. ...")
    assert game.play(board("XXO .O. ..."), 3, steals=1) == board("XXO XO. ...")


def test_steal_turns_an_o_into_an_x() -> None:
    before = board("XO. .O. ..X")
    after = game.steal(before, 1, 0)
    assert after == board("XX. .O. ..X")
    assert before == board("XO. .O. ..X"), "steal must not change its input"
    assert game.turn(after, steals=1) == "O", "the steal is X's move"


def test_a_steal_can_win_at_once() -> None:
    after = game.steal(board("XO. .O. ..X"), 4, 0)
    result = game.outcome(after)
    assert (result.status, result.winner, result.line) == ("won", "X", (0, 4, 8))


def test_a_steal_never_adds_a_mark() -> None:
    before = board("XO. .O. ..X")
    after = game.steal(before, 1, 0)
    assert after.count("") == before.count("")


def test_only_one_steal_per_game() -> None:
    with pytest.raises(game.IllegalMoveError, match="already stolen"):
        game.steal(board("XXO .O. ..X"), 2, 1)


@pytest.mark.parametrize("cell", [-1, 9, "4", 4.0, True, False, None])
def test_steal_rejects_cells_that_are_not_squares(cell: object) -> None:
    with pytest.raises(game.IllegalMoveError, match="steal must be a whole number from 0 to 8"):
        game.steal(board("XO. .O. ..X"), cell, 0)


@pytest.mark.parametrize("cell", [0, 2, 8])
def test_steal_only_takes_the_computers_squares(cell: int) -> None:
    with pytest.raises(game.IllegalMoveError, match="one of the computer's squares"):
        game.steal(board("XO. .O. ..X"), cell, 0)


def test_steal_rejects_a_finished_game() -> None:
    with pytest.raises(game.IllegalMoveError, match="the game is over"):
        game.steal(board("XX. OOO X.."), 3, 0)


def test_steal_only_on_xs_turn() -> None:
    with pytest.raises(game.IllegalMoveError, match="you play X"):
        game.steal(board("XO. X.. ..."), 1, 0)


def test_steal_checks_in_the_specs_order() -> None:
    # already stolen comes before a bad cell, a bad cell before game over,
    # game over before "not an O"
    with pytest.raises(game.IllegalMoveError, match="already stolen"):
        game.steal(board("XO. ... ..."), "x", 1)
    with pytest.raises(game.IllegalMoveError, match="whole number"):
        game.steal(board("XX. OOO X.."), 9, 0)
    with pytest.raises(game.IllegalMoveError, match="over"):
        game.steal(board("XX. OOO X.."), 0, 0)

