def test_steal_rejects_cells_that_are_not_squares(cell: object) -> None:
    with pytest.raises(game.IllegalMoveError, match="steal must be a whole number from 0 to 8"):
        game.steal(board("XO. .O. ..X"), cell, 0)


@pytest.mark.parametrize("cell", [0, 2, 8])
def test_steal_only_takes_the_computers_squares(cell: int) -> None:
    with pytest.raises(game.IllegalMoveError, match="one of the computer's squares"):
        game.steal(board("XO. .O. ..X"), cell, 0)


def test_steal_rejects_a_finished_game() -> None:
    with pytest.raises(game.IllegalMoveError, match="the game is over"):
        game.steal(board("XX. OOO X.."), 3, 0)


def test_steal_only_on_xs_turn() -> None:
    with pytest.raises(game.IllegalMoveError, match="you play X"):
        game.steal(board("XO. X.. ..."), 1, 0)


def test_steal_checks_in_the_specs_order() -> None:
    # already stolen comes before a bad cell, a bad cell before game over,
    # game over before "not an O"
    with pytest.raises(game.IllegalMoveError, match="already stolen"):
        game.steal(board("XO. ... ..."), "x", 1)
    with pytest.raises(game.IllegalMoveError, match="whole number"):
        game.steal(board("XX. OOO X.."), 9, 0)
    with pytest.raises(game.IllegalMoveError, match="over"):
        game.steal(board("XX. OOO X.."), 0, 0)

